let sum = 0;
for (let i = 0; i < 100; i++) {
    if (i % 3 == 0 || i % 5 == 0) {
        sum += i;
    }
}
print(sum);

fn isLeap(year) {
    return (year % 400 == 0) || ((year % 4 == 0) && (year % 100 != 0));
}
print(isLeap(1900));
print(isLeap(2000));
print(isLeap(2024));
print(isLeap(2023));

fn toFahrenheit(c) {
    return c * 9 / 5 + 32;
}
print(toFahrenheit(0));
print(toFahrenheit(100));
print(toFahrenheit(-40));
